var WebsocketConnection = class extends Connection {
	ws;
	get state() {
		return this.ws.readyState;
	}
	get bufferedAmount() {
		return this.ws.bufferedAmount;
	}
	constructor(address) {
		super();
		this.ws = new WebSocket(address);
		this.ws.binaryType = "arraybuffer";
		this.ws.onopen = () => {
			this.onOpen();
		};
		this.ws.onmessage = (e) => {
			this.onMessage(e.data);
		};
		this.ws.onclose = (e) => {
			this.onClose(e.code, e.reason);
		};
		this.ws.onerror = () => {
			this.onError();
		};
	}
	send(data) {
		this.ws.send(data);
	}
	close(reason) {
		if (reason) this.ws.close(3e3, reason);
		else this.ws.close();
	}
};

