//#region src/objects/explosion.ts
var PhysicsParticle = class {
	active;
	pos;
	vel;
	layer;
	particle;
	ticker;
	colCount;
	constructor() {
		this.active = false;
	}
	init(pos, vel, layer, particle) {
		this.pos = v2.copy(pos);
		this.vel = v2.copy(vel);
		this.layer = layer;
		this.particle = particle;
		this.ticker = 0;
		this.colCount = 0;
		this.active = true;
	}
	update(dt, map, playerBarn) {
		const posOld = v2.copy(this.pos);
		this.pos = v2.add(this.pos, v2.mul(this.vel, dt));
		this.vel = v2.mul(this.vel, 1 / (1 + dt * 5));
		const colliders = [];
		const obstacles = map.m_obstaclePool.m_getPool();
		for (let i = 0; i < obstacles.length; i++) {
			const obstacle = obstacles[i];
			if (obstacle.active && !obstacle.dead && util.sameLayer(this.layer, obstacle.layer)) colliders.push(obstacle.collider);
		}
		const players = playerBarn.playerPool.m_getPool();
		for (let i = 0; i < players.length; i++) {
			const player = players[i];
			if (player.active && !player.m_netData.m_dead && util.sameLayer(this.layer, player.layer)) colliders.push(collider.createCircle(player.m_pos, player.m_rad));
		}
		const cols = [];
		for (let i = 0; i < colliders.length; i++) {
			const res = collider.intersectSegment(colliders[i], posOld, this.pos);
			if (res) {
				const dist = v2.length(v2.sub(res.point, posOld));
				cols.push({
					point: res.point,
					normal: res.normal,
					dist
				});
			}
		}
		cols.sort((a, b) => {
			return a.dist - b.dist;
		});
		if (cols.length > 0) {
			const col = cols[0];
			const dir = v2.normalizeSafe(this.vel, v2.create(1, 0));
			const spd = v2.length(this.vel);
			const reflectDir = v2.sub(dir, v2.mul(col.normal, v2.dot(col.normal, dir) * 2));
			const friction = this.colCount++ > 0 ? .35 : 1;
			this.pos = v2.add(col.point, v2.mul(col.normal, .01));
			this.vel = v2.mul(reflectDir, spd * friction);
		}
		this.particle.pos = v2.copy(this.pos);
		this.ticker += dt;
		if (this.ticker >= this.particle.life) {
			this.particle.free();
			this.active = false;
		}
	}
};
var Explosion = class {
	active;
	type;
	done;
	pos;
	layer;
	ticker;
	lifetime;
	soundInstance;
	soundUpdateThrottle;
	constructor() {
		this.active = false;
	}
	init(type, pos, layer) {
		const expType = GameObjectDefs.typeToDef(type, "explosion").explosionEffectType;
		const def = ExplosionEffectDefs[expType];
		this.active = true;
		this.done = false;
		this.type = type;
		this.pos = v2.copy(pos);
		this.layer = layer;
		this.ticker = 0;
		this.lifetime = def.lifetime;
		this.soundInstance = null;
		this.soundUpdateThrottle = 0;
	}
	free() {
		this.active = false;
	}
	update(dt, explosionBarn, particleBarn, audioManager, map, camera) {
		const expType = GameObjectDefs.typeToDef(this.type, "explosion").explosionEffectType;
		const def = ExplosionEffectDefs[expType];
		if (this.ticker == 0) {
			let renderVisuals = true;
			if (this.type == "explosion_bomb_iron") {
				const col = collider.createCircle(this.pos, .5);
				if (map.insideBuildingCeiling(col, true)) renderVisuals = false;
			}
			if (renderVisuals && (def.burst.particle && particleBarn.addParticle(def.burst.particle, this.layer, this.pos, v2.create(0, 0), def.burst.scale, 0, null), def.scatter)) for (let i = 0; i < def.scatter.count; i++) {
				const particle = particleBarn.addParticle(def.scatter.particle, this.layer, this.pos, v2.create(0, 0), 1, 0, null);
				const physPart = explosionBarn.addPhysicsParticle();
				const vel = v2.randomUnit(util.random(def.scatter.speed.min, def.scatter.speed.max));
				physPart.init(this.pos, vel, this.layer, particle);
			}
			const surface = map.getGroundSurface(this.pos, this.layer);
			const sound = surface.type == "water" ? def.burst.sound.water : def.burst.sound.grass;
			let detune = 0;
			if (def.burst.sound.detune != void 0) detune = def.burst.sound.detune;
			let volume = 1;
			if (def.burst.sound.volume != void 0) volume = def.burst.sound.volume;
			this.soundInstance = audioManager.playSound(sound, {
				channel: "sfx",
				soundPos: this.pos,
				layer: this.layer,
				filter: "muffled",
				rangeMult: 2,
				ignoreMinAllowable: true,
				detune,
				volumeScale: volume
			});
			if (surface.type == "water") for (let i = 0; i < def.rippleCount; i++) {
				const maxRad = def.rippleCount * .5;
				const ripplePos = v2.add(this.pos, v2.randomUnit(util.random(0, maxRad)));
				particleBarn.addRippleParticle(ripplePos, this.layer, surface.data.rippleColor).setDelay(i * .06);
			}
		}
		if (this.soundInstance && this.soundUpdateThrottle < 0) {
			this.soundUpdateThrottle = .1;
			let volume = 1;
			if (def.burst.sound.volume != void 0) volume = def.burst.sound.volume;
			audioManager.updateSound(this.soundInstance, "sfx", this.pos, {
				layer: this.layer,
				filter: "muffled",
				volumeScale: volume
			});
		} else this.soundUpdateThrottle -= dt;
		this.ticker += dt;
		const shakeT = math.min(this.ticker / def.shakeDur, 1);
		const shakeInt = math.lerp(shakeT, def.shakeStr, 0);
		camera.m_addShake(this.pos, shakeInt);
		if (this.ticker >= this.lifetime) this.active = false;
	}
};
var ExplosionBarn = class {
	explosions;
	physicsParticles;
	constructor() {
		this.explosions = [];
		this.physicsParticles = [];
	}
	addExplosion(type, pos, layer) {
		let explosion = null;
		for (let i = 0; i < this.explosions.length; i++) if (!this.explosions[i].active) {
			explosion = this.explosions[i];
			break;
		}
		if (!explosion) {
			explosion = new Explosion();
			this.explosions.push(explosion);
		}
		explosion.init(type, pos, layer);
	}
	addPhysicsParticle() {
		let p = null;
		for (let i = 0; i < this.physicsParticles.length; i++) {
			const particle = this.physicsParticles[i];
			if (!particle.active) {
				p = particle;
				break;
			}
		}
		if (!p) {
			p = new PhysicsParticle();
			this.physicsParticles.push(p);
		}
		return p;
	}
	m_update(dt, map, playerBarn, camera, particleBarn, audioManager, debug) {
		for (let i = 0; i < this.explosions.length; i++) {
			const e = this.explosions[i];
			if (e.active) {
				e.update(dt, this, particleBarn, audioManager, map, camera);
				if (!e.active) e.free();
			}
		}
		for (let i = 0; i < this.physicsParticles.length; i++) {
			const p = this.physicsParticles[i];
			if (p.active) p.update(dt, map, playerBarn);
		}
	}
};
