var submergeMaskScaleFactor = .1;
function perksEqual(a, b) {
	if (a.length != b.length) return false;
	for (let i = 0; i < a.length; i++) if (a[i].type != b[i].type) return false;
	return true;
}
function createPlayerNameText() {
	const nameStyle = {
		fontFamily: "Arial",
		fontWeight: "bold",
		fontSize: device.pixelRatio > 1 ? 30 : 22,
		align: "center",
		fill: 65535,
		stroke: 0,
		strokeThickness: 0,
		dropShadow: true,
		dropShadowColor: "#000000",
		dropShadowBlur: 1,
		dropShadowAngle: Math.PI / 3,
		dropShadowDistance: 1
	};
	const nameText = new Text("", nameStyle);
	nameText.anchor.set(.5, .5);
	nameText.scale.set(.5, .5);
	nameText.position.set(0, 30);
	nameText.visible = false;
	return nameText;
}
function createSprite() {
	const sprite = new Sprite();
	sprite.texture = Texture.EMPTY;
	sprite.anchor.set(.5, .5);
	sprite.scale.set(1, 1);
	sprite.tint = 16777215;
	sprite.visible = false;
	return sprite;
}
